changeSet.sql:
-- Add or update extended property on schema (SQL Server equivalent of schema comment)
IF EXISTS (SELECT * FROM sys.extended_properties WHERE major_id = SCHEMA_ID('RedGate') AND name = 'MS_Description')
BEGIN
  EXEC sys.sp_updateextendedproperty 
    @name = N'MS_Description',
    @value = N'Liquibase SQL Server test schema (updated)',
    @level0type = N'SCHEMA',
    @level0name = N'RedGate'
END
ELSE
BEGIN
  EXEC sys.sp_addextendedproperty 
    @name = N'MS_Description',
    @value = N'Liquibase SQL Server test schema (updated)',
    @level0type = N'SCHEMA',
    @level0name = N'RedGate'
END


CREATE VIEW RedGate.FeedbackAuditSummary AS
SELECT AuditID, CustomerID AS CustID, CreatedAt
FROM RedGate.FeedbackAudit;

CREATE FUNCTION RedGate.count_recent_audits(@p_days INT) RETURNS INT AS BEGIN DECLARE @v_count INT;
-- Updated logic: same functionality but clearer SQL Server syntax SELECT @v_count = COUNT(*) FROM RedGate.FeedbackAudit a WHERE a.CreatedAt > DATEADD(DAY, -@p_days, SYSDATETIMEOFFSET());
RETURN @v_count; END
